import{_ as a,o as i,c as t,aj as s}from"./chunks/framework.C6uXqnaX.js";const k=JSON.parse('{"title":"Disallowed function call inside reactive context","description":"","frontmatter":{},"headers":[],"relativePath":"en/errors/NG0602.md","filePath":"en/errors/NG0602.md"}'),n={name:"en/errors/NG0602.md"};function o(r,e,l,d,c,h){return i(),t("div",null,e[0]||(e[0]=[s('<h1 id="disallowed-function-call-inside-reactive-context" tabindex="-1">Disallowed function call inside reactive context <a class="header-anchor" href="#disallowed-function-call-inside-reactive-context" aria-label="Permalink to &quot;Disallowed function call inside reactive context&quot;">​</a></h1><p>A function that is not allowed to run inside a reactive context was called from within a reactive context.</p><p>For example, an <code>effect</code> cannot be scheduled from within a <code>computed</code> or an actively executing effect. Avoid calling functions like <code>effect</code> as part of template expressions, as those execute in their own reactive context.</p><p>Computed expressions are expected to be pure. Pure means that expression do not trigger any side effects. Side effects are operations like scheduling <code>afterNextRender</code>/<code>afterEveryRender</code>, creating a new <code>effect</code>, or subscribing to observables.</p><p>Some operations are explicitly banned inside reactive contexts in order to avoid common pitfalls. As an example, using <code>afterNextRender</code>/<code>afterEveryRender</code> inside a <code>computed</code> will schedule new render hooks every time the computed expression evaluates. This is likely not intended and could degrade application performance.</p><h3 id="fixing-the-error" tabindex="-1">Fixing the error <a class="header-anchor" href="#fixing-the-error" aria-label="Permalink to &quot;Fixing the error&quot;">​</a></h3><p>This error guide is non-exhaustive. It captures a few common scenarios and how to address the error.</p><h4 id="afternextrender-aftereveryrender" tabindex="-1"><code>afterNextRender</code>/<code>afterEveryRender</code> <a class="header-anchor" href="#afternextrender-aftereveryrender" aria-label="Permalink to &quot;`afterNextRender`/`afterEveryRender`&quot;">​</a></h4><p>Move the call for <code>afterNextRender</code>/<code>afterEveryRender</code> outside of the reactive context.</p><p>A good place to schedule the after render hook is in the component&#39;s class constructor. Alternatively, use <code>untracked</code> to leave the reactive context and explicitly opt-out of this error.</p><h4 id="effect" tabindex="-1"><code>effect</code> <a class="header-anchor" href="#effect" aria-label="Permalink to &quot;`effect`&quot;">​</a></h4><p>Move the call for <code>effect</code> outside of the reactive context.</p><p>A good place to schedule an effect is in a <code>@Component</code>&#39;s class constructor.</p><h4 id="tosignal" tabindex="-1"><code>toSignal</code> <a class="header-anchor" href="#tosignal" aria-label="Permalink to &quot;`toSignal`&quot;">​</a></h4><p>Move the call for <code>toSignal</code> outside of the reactive context.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> computed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> dataSignal</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> toSignal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dataObservable$);</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> doSomething</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dataSignal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>can be refactored into:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dataSignal </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> toSignal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dataObservable$);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> computed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> doSomething</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dataSignal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()));</span></span></code></pre></div><p>Alternatively, if this is not possible, consider manually subscribing to the observable.</p><p>As a last resort, use <code>untracked</code> to leave the reactive context. Be careful as leaving the reactive context can result in signal reads to be ignored inside <code>untracked</code>.</p><h3 id="debugging-the-error" tabindex="-1">Debugging the error <a class="header-anchor" href="#debugging-the-error" aria-label="Permalink to &quot;Debugging the error&quot;">​</a></h3><p>The error message mentions the function that was unexpectedly called. Look for this function call in your application code.</p><p>Alternatively, the stack trace in your browser will show where the function was invoked and where it&#39;s located.</p>',23)]))}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
